import Tooltip from '@jetbrains/ring-ui-built/components/tooltip/tooltip'
import classNames from 'classnames'
import {useMemo} from 'react'

import useMyId from '../../../../../hooks/useMyId'
import {getPipelineHref} from '../../../../../routes'
import {getBuildStatusIconFromBuild, getBuildStatusTypeFromBuild} from '../../../../../selectors'
import type {Build} from '../../../../../services/rest'
import type {PipelineId} from '../../../../../types'
import {BuildStatusType} from '../../../../../types'
import {useTitle} from '../../../../common/BuildStatus/BuildStatusLink/BuildStatusLink.utils'
import RouterLink from '../../../../common/RouterLink/RouterLink'
import {usePipelineId} from '../../hooks/pipeline'
import JobIconStatus from '../JobIconStatus/JobIconStatus'
import ReusedJobStatusLink from '../ReusedJobStatusLink/ReusedJobStatusLink'

import {getJobWaitReason} from './RunStatus.utils'

import styles from './RunStatus.module.css'

type BaseProps = {
  className?: string
  withLink?: boolean
  withIcon?: boolean
  pipelineId?: PipelineId
  omitUnknown?: boolean
  reused?: boolean
  isIncompatibilityAgent?: boolean
}

type Props = Pick<
  Build,
  | 'id'
  | 'status'
  | 'state'
  | 'parallelized'
  | 'canceledInfo'
  | 'failedToStart'
  | 'statusText'
  | 'waitReason'
  | 'startEstimate'
> &
  BaseProps

export default function RunStatus({
  className,
  withLink = true,
  withIcon = true,
  pipelineId,
  omitUnknown,
  reused,
  isIncompatibilityAgent,
  ...run
}: Props) {
  const runId = String(run.id)
  const pipelineIdFromUrl = usePipelineId()
  const href = getPipelineHref(pipelineId ?? pipelineIdFromUrl, runId)
  const {statusText, state, parallelized, startEstimate} = run
  const isShowIncompatibilityAgentStatus =
    isIncompatibilityAgent && state === BuildStatusType.QUEUED
  const runStatusType = isShowIncompatibilityAgentStatus
    ? 'warning'
    : getBuildStatusTypeFromBuild(run)
  const waitReason = getJobWaitReason(run)
  const runStatus = useTitle({
    statusText,
    isQueued: state === 'queued',
    waitReason,
    startEstimate,
    omitUnknown,
  })
  const myId = useMyId()
  const icon = getBuildStatusIconFromBuild(run, myId)
  const wrapperClassName = classNames(className, styles[runStatusType])
  const content = useMemo(() => {
    if (isShowIncompatibilityAgentStatus) {
      return 'No compatible agent'
    }

    return (
      <Tooltip
        title={<div className={classNames(styles.tooltipText)}>{runStatus}</div>}
        popupProps={{
          className: styles.popupTooltip,
        }}
      >
        {withIcon && (
          <JobIconStatus
            parallelized={parallelized}
            icon={icon}
            status={runStatusType}
            className={styles.icon}
          />
        )}
        {reused ? (
          <ReusedJobStatusLink
            jobId={runId}
            placeholder={statusText}
            suffix=" Job reused"
            prefix={`${runStatus}/ `}
          />
        ) : (
          runStatus
        )}
      </Tooltip>
    )
  }, [
    icon,
    isShowIncompatibilityAgentStatus,
    parallelized,
    reused,
    runId,
    runStatus,
    runStatusType,
    statusText,
    withIcon,
  ])

  return withLink ? (
    <RouterLink to={href} className={wrapperClassName}>
      {content}
    </RouterLink>
  ) : (
    <span className={wrapperClassName}>{content}</span>
  )
}
