import {SvgIcon} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import {memo} from 'react'

import {BuildStatusType} from '../../../../../types'
import Icon from '../../../../common/Icon/Icon'

import type {JobIconStatusProps} from './JobIconStatus.types'

import styles from './JobIconStatus.module.css'

function JobIconStatus({icon, parallelized, status, state, className}: JobIconStatusProps) {
  const isError = status?.toLowerCase() === 'failure'
  const isSuccess = status?.toLowerCase() === 'success'
  const isQueued = state === BuildStatusType.QUEUED

  const iconsWrapperClassName = classNames(styles.iconsWrapper, className)
  const parallelismIconClassName = classNames(styles.parallelismIcon, {
    [styles.parallelismIconSuccess]: isSuccess,
    [styles.parallelismIconError]: isError,
  })

  return (
    <span className={iconsWrapperClassName}>
      <Icon className={styles.icon} name={icon} />
      {parallelized && !isQueued && <SvgIcon className={parallelismIconClassName} icon="stack" />}
    </span>
  )
}

export default memo(JobIconStatus)
