import {Directions} from '@jetbrains/ring-ui-built/components/popup/popup.consts'
import classNames from 'classnames'
import type {LinkProps} from 'react-router'

import {getBuildStatusTypeFromBuild} from '../../../../../selectors'
import type {Build, ProgressInfo} from '../../../../../services/rest'
import {formatDuration} from '../../../../../utils/dateTimeUtils'
import BuildArtifacts from '../../../../common/BuildArtifacts/BuildArtifacts'
import PipelineRunJobProgress from '../../PipelineRunPage/PipelineTab/PipelineRunChart/PipelineRunJob/PipelineRunJobProgress/PipelineRunJobProgress'
import JobIconStatus from '../JobIconStatus/JobIconStatus'
import JobTile, {JobTileType} from '../JobTile/JobTile'
import RunStatus from '../RunStatus/RunStatus'

import styles from './RunJob.module.css'

import type {BuildId} from 'src/types'
import {BuildStatusType} from 'src/types'

const RunStatusJobTileTypeMap = {
  [BuildStatusType.FAILURE]: JobTileType.ERROR,
  [BuildStatusType.QUEUED]: JobTileType.DEFAULT,
  [BuildStatusType.SUCCESS]: JobTileType.SUCCESS,
  [BuildStatusType.CANCELED]: JobTileType.CANCELED,
}

type BaseProps = {
  jobId?: BuildId | null
  runningInfo?: ProgressInfo | null
  parallelTestsRuns?: Build[]
  isJobReused?: boolean
  selectedJobId?: BuildId | null
  icon: string
  isIncompatibilityAgent?: boolean
  position?: {
    x: number
    y: number
  }
}

type Props = Pick<
  Build,
  'status' | 'state' | 'parallelized' | 'buildType' | 'statusText' | 'artifacts'
> &
  Pick<LinkProps, 'to' | 'replace'> &
  BaseProps

export default function RunJob({
  position,
  jobId,
  isJobReused,
  parallelTestsRuns,
  runningInfo,
  selectedJobId,
  icon,
  replace,
  to,
  ...job
}: Props) {
  const {state, parallelized, buildType, artifacts} = job ?? {}
  const {percentageComplete, leftSeconds} = runningInfo ?? {}
  const runStatusType = getBuildStatusTypeFromBuild(job)

  const isRunning = state === 'running'
  const isFailing = isRunning && runStatusType === BuildStatusType.FAILURE

  const topLeft = (
    <>
      <JobIconStatus
        className={classNames({
          [styles.running]: isRunning || runStatusType === BuildStatusType.QUEUED,
          [styles.failure]: isFailing,
        })}
        parallelized={parallelized}
        icon={icon}
        status={job?.status}
        state={runStatusType}
      />
      {leftSeconds != null && (
        <span className={styles.left}>{`${formatDuration(leftSeconds)} left`}</span>
      )}
    </>
  )
  const topRight =
    artifacts?.count != null && artifacts.count > 0 && jobId ? (
      <BuildArtifacts
        className={styles.artifacts}
        buildType={buildType?.id}
        buildId={jobId}
        popupOffset={4}
        popupDirection={[
          Directions.RIGHT_BOTTOM,
          Directions.RIGHT_TOP,
          Directions.LEFT_BOTTOM,
          Directions.LEFT_TOP,
        ]}
        wrapperProps={{
          onClick: e => e.preventDefault(),
        }}
        hasArtifacts
      />
    ) : null
  const statusBlock = (
    <RunStatus
      className={classNames(styles.runStatus, {
        [styles.running]: isRunning,
        [styles.failure]: isFailing,
      })}
      id={jobId}
      {...job}
      reused={isJobReused}
      withLink={false}
      withIcon={false}
      omitUnknown
    />
  )
  const jobProgress = percentageComplete ? (
    <PipelineRunJobProgress
      mainPercentage={percentageComplete}
      builds={parallelTestsRuns}
      status={runStatusType}
    />
  ) : null

  return (
    <JobTile
      className={classNames({[styles.absolute]: position != null})}
      topLeft={topLeft}
      topRight={topRight}
      status={statusBlock}
      progress={jobProgress}
      style={position ? {top: position.x, left: position.y} : {}}
      name={buildType?.name}
      selected={jobId === selectedJobId}
      type={
        isRunning && runStatusType === BuildStatusType.SUCCESS
          ? JobTileType.RUNNING
          : RunStatusJobTileTypeMap[runStatusType]
      }
      to={to}
      replace={replace}
    />
  )
}
