import classNames from 'classnames'
import {memo} from 'react'

import usePipelineRunJobProgress from './PipelineRunJobProgress.hooks'
import type {PipelineRunJobProgressProps} from './PipelineRunJobProgress.types'

import styles from './PipelineRunJobProgress.module.css'

function PipelineRunJobProgress({mainPercentage, builds, status}: PipelineRunJobProgressProps) {
  const {progressPercentages, progresBarHeight} = usePipelineRunJobProgress(mainPercentage, builds)
  const progresBarClassNames = classNames(styles.progressBar, {
    [styles.progressFailure]: status === 'failure',
    [styles.progressSuccess]: status === 'success',
  })

  return (
    <div className={styles.progress}>
      {progressPercentages.filter(Number).map((percentage, index) => {
        const key = `key_${index}`
        return (
          <div
            className={progresBarClassNames}
            key={key}
            style={{width: `${percentage}%`, height: `${progresBarHeight}%`}}
          />
        )
      })}
    </div>
  )
}

export default memo(PipelineRunJobProgress)
