import {WaitReasons} from '../../../../common/BuildQueueInfo/BuildQueueInfo.consts'

const ignoredReasons: string[] = [
  WaitReasons.DEPENDENCY_NOT_READY,
  WaitReasons.WAITING_CHECKING_FOR_CHANGES,
  WaitReasons.WAITING_FOR_THE_FIRST_DEPENDENCY_TO_START,
  WaitReasons.CHECKING_FOR_CHANGES_IN_PROGRESS,
]

export function getJobWaitReason(job: {waitReason?: string | undefined | null}) {
  const {waitReason} = job
  return ignoredReasons.includes(waitReason!) ? '' : waitReason
}
