import icon from '@jetbrains/icons/pipeline.svg'
import {H3} from '@jetbrains/ring-ui-built/components/heading/heading'
import {SvgIcon} from '@jetbrains/teamcity-ui/dist/components'
import {skipToken} from '@reduxjs/toolkit/query'
import plur from 'plur'
import {memo} from 'react'

import {restApi} from '../../../../../services/rest'

import JobTile from './JobTile'

import styles from './JobList.module.css'

interface Props {
  buildIds: Array<number>
}

function JobList(props: Props) {
  const {buildIds} = props

  const {groupedBuilds} = restApi.endpoints.getBuilds.useQuery(
    buildIds.length > 0
      ? {
          buildLocator: buildIds.map(id => `item:(id:${id})`).join(','),
          fields: 'build(id,pipelineRunJob(pipelineRun(pipeline(id,name))))',
        }
      : skipToken,
    {
      selectFromResult: ({data}) => ({
        groupedBuilds: data?.build.reduce<Record<string, {name: string; ids: number[]}>>(
          (acc, build) => {
            const {id, name} = build.pipelineRunJob?.pipelineRun?.pipeline ?? {}
            if (id && build.id) {
              acc[id] = acc[id] ?? {name, ids: []}
              acc[id].ids.push(build.id)
            }
            return acc
          },
          {},
        ),
      }),
    },
  )

  return (
    buildIds.length > 0 &&
    groupedBuilds && (
      <>
        <H3
          className={styles.title}
        >{`${buildIds.length} running ${plur('job', buildIds.length)}`}</H3>
        {Object.entries(groupedBuilds).map(([pipelineId, {name, ids}]) => (
          <div key={pipelineId} className={styles.pipelineGroup}>
            <div className={styles.pipelineName}>
              <SvgIcon className={styles.icon} icon={icon} />
              {name}
            </div>
            <div className={styles.list}>
              {ids.map(id => (
                <JobTile key={id} buildId={id} />
              ))}
            </div>
          </div>
        ))}
      </>
    )
  )
}

export default memo(JobList)
