import merge from 'lodash/merge'
import {useEffect, useMemo} from 'react'

import {useAppDispatch} from '../../../../../hooks/react-redux'
import type {GetBuildApiArg} from '../../../../../services/rest'
import {restApi} from '../../../../../services/rest'
import {subscribeOnRunningBuild} from '../../../../../utils/subscriber'
import {useJobParallelRuns} from '../../hooks/useJobParallelRuns'

const useJobArg = (buildId: number): GetBuildApiArg =>
  useMemo(
    () => ({
      buildLocator: `id:${buildId}`,
      fields:
        'attributes($locator(name:teamcity.pipeline.job.id),entry(name,value)),' +
        'id,state,status,statusText,number,canceledInfo,failedToStart,personal,detachedFromAgent' +
        ',parallelized,waitReason,startEstimate,startDate,finishDate,user(id),buildType(id,name,project(internalId))' +
        ',running-info(percentageComplete,leftSeconds),artifacts(count)' +
        ',snapshot-dependencies(build(id,running-info(percentageComplete),buildType(project(internalId))))' +
        ',pipelineRunJob(pipelineRun(build(id),pipeline(id)))',
    }),
    [buildId],
  )

export const useJobTile = (buildId: number) => {
  const arg = useJobArg(buildId)
  const {job} = restApi.endpoints.getBuild.useQuery(arg, {
    selectFromResult: ({data}) => ({
      job: data,
    }),
  })
  const isRunning = job?.state === 'running'
  const dispatch = useAppDispatch()

  useEffect(() => {
    if (isRunning) {
      return subscribeOnRunningBuild(buildId, data =>
        dispatch(
          restApi.util.updateQueryData('getBuild', arg, draft => {
            merge(draft, data)
          }),
        ),
      )
    }
    return undefined
  }, [arg, isRunning, buildId, dispatch])
  const parallelTestsRuns = useJobParallelRuns(job)

  return {job, parallelTestsRuns}
}
