import {memo, useMemo} from 'react'

import useMyId from '../../../../../hooks/useMyId'
import {getPipelineHref} from '../../../../../routes'
import {getBuildStatusIconFromBuild} from '../../../../../selectors'
import RunJob from '../../components/RunJob/RunJob'

import {useJobTile} from './JobTile.hooks'

interface Props {
  buildId: number
}

function JobTile(props: Props) {
  const {buildId} = props
  const {job, parallelTestsRuns} = useJobTile(buildId)

  const runningInfo = job?.['running-info']
  const myId = useMyId()
  const icon = getBuildStatusIconFromBuild(job, myId, false, job?.personal ?? false)
  const pipelineId = job?.pipelineRunJob?.pipelineRun?.pipeline?.id
  const userId = job?.user?.id
  const isCurrentUser = userId != null && userId === myId

  const to = useMemo(() => {
    if (job?.personal) {
      return isCurrentUser && pipelineId != null
        ? {pathname: getPipelineHref(pipelineId), search: `edit=true`}
        : {}
    }
    return {
      pathname:
        pipelineId != null
          ? getPipelineHref(pipelineId, String(job?.pipelineRunJob?.pipelineRun?.build?.id))
          : undefined,
      search: `job=${buildId}`,
    }
  }, [buildId, job, isCurrentUser, pipelineId])

  return (
    job && (
      <RunJob
        jobId={buildId}
        runningInfo={runningInfo}
        isJobReused={false}
        parallelTestsRuns={parallelTestsRuns}
        selectedJobId={null}
        icon={icon}
        to={to}
        replace
        {...job}
      />
    )
  )
}

export default memo(JobTile)
